export function mergeHarnessLocale<T extends Record<string, unknown>>(
  localeKey: LocaleKey,
  messages: T
): T {
  const harnessPatch = mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(
        mergeLocaleNodes(
          baseHarnessPatch as LocaleNode,
          (localeHarnessOverrides[localeKey] ?? {}) as LocaleNode
        ),
        (legacyHarnessPatches[localeKey] ?? {}) as LocaleNode
      ),
      (bundleDatasetLocaleOverrides[localeKey] ?? {}) as LocaleNode
    ),
    (harnessGroupBackfills[localeKey] ?? {}) as LocaleNode
  )
  const structuralPatch = mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(
        (localeStructuralBackfills[localeKey] ?? {}) as LocaleNode,
        (skillStoreHighRiskBackfills[localeKey] ?? {}) as LocaleNode
      ),
      mergeLocaleNodes(
        mergeLocaleNodes(
          mergeLocaleNodes(
            knowledgeLocaleBase,
            (extensionsBrowseBackfills[localeKey] ?? {}) as LocaleNode
          ),
          (automationKnowledgeEvolutionBackfills[localeKey] ?? {}) as LocaleNode
        ),
        (evolutionUILocaleBackfills[localeKey] ?? {}) as LocaleNode
      )
    ),
    (localeFollowupBackfills[localeKey] ?? {}) as LocaleNode
  )
  const securityCronMaskingPatch = (securityCronMaskingBackfills[localeKey] ?? {}) as LocaleNode
  const mergedMessages = mergeLocaleNodes(
    mergeLocaleNodes(structuralPatch, securityCronMaskingPatch),
    messages as unknown as LocaleNode
  )
  const skillStorePatch = buildSkillStoreDerivedBackfill(
    localeKey,
    mergedMessages as unknown as Record<string, unknown>
  ) as LocaleNode
  const mergedWithSkillStore = mergeLocaleNodes(mergedMessages, skillStorePatch)
  const postMergePatch = buildLocalePostMergeBackfill(
    localeKey,
    mergedWithSkillStore as unknown as Record<string, unknown>
  ) as LocaleNode
  const mergedWithPostMerge = mergeLocaleNodes(mergedWithSkillStore, postMergePatch)
  const settingsPatch = mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(agentcoreRunnerSettingsBase, agentcoreRunnerPartSettingsBase as LocaleNode),
      agentcoreRunnerPartDescriptionBase as LocaleNode
    ),
    mergeLocaleNodes(
      mergeLocaleNodes(
        (agentcoreRunnerSettingsOverrides[localeKey] ?? {}) as LocaleNode,
        (agentcoreRunnerPartSettingsOverrides[localeKey] ?? {}) as LocaleNode
      ),
      (agentcoreRunnerPartDescriptionOverrides[localeKey] ?? {}) as LocaleNode
    )
  )
  const currentHarness = (mergedWithPostMerge.harness ?? {}) as LocaleNode
  const currentSettings = (mergedWithPostMerge.settings ?? {}) as LocaleNode
  const evolutionUIOverrides = (evolutionUILocaleBackfills[localeKey] ?? {}) as LocaleNode
  const operationsRenameOverrides = (automationOperationsRenameBackfills[localeKey] ?? {}) as LocaleNode
  const evolutionChineseOperatorOverrides = (evolutionChineseOperatorBackfills[localeKey] ??
    {}) as LocaleNode

  const mergedHarnessAndSettings = {
    ...(mergedWithPostMerge as T),
    settings: mergeLocaleNodes(currentSettings, {
      agentcoreRunner: settingsPatch,
    } as LocaleNode),
    harness: mergeLocaleNodes(currentHarness, harnessPatch),
  } as T

  return mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(mergedHarnessAndSettings as unknown as LocaleNode, evolutionUIOverrides),
      operationsRenameOverrides
    ),
    evolutionChineseOperatorOverrides
  ) as T
}
